// docs/adr/0007-async-messaging-between-order-and-billing.md
//
// # 7. Asynchronous messaging between Order and Billing
//
// ## Status
// Accepted — 2026-03-14
//
// ## Context
// Order submission currently calls Billing over HTTP synchronously. Billing's
// p99 is 1.8s and its maintenance windows take order submission down with it.
// Order volume is projected to triple within a year.
//
// ## Decision
// Order publishes OrderSubmitted to Azure Service Bus. Billing subscribes and
// processes independently. Order returns as soon as the message is durably
// enqueued.
//
// ## Alternatives considered
// - Keep synchronous HTTP with retries and a circuit breaker.
//   Rejected: does not decouple availability; a Billing outage still fails orders.
// - Dual-write to a shared database table polled by Billing.
//   Rejected: couples the two schemas and reintroduces the shared-database problem.
//
// ## Consequences
// + Order availability no longer depends on Billing availability.
// + Each service scales on its own load profile.
// - The system becomes eventually consistent; the UI must show "billing pending".
// - Message ordering and duplicate delivery now need explicit handling.
// - Operational surface grows: a dead-letter queue needs monitoring and an owner.

// Application layer — declares what it needs, knows no SDK.
namespace Acme.Application.Abstractions;

public interface IEmbeddingProvider
{
    Task<ReadOnlyMemory<float>> EmbedAsync(string text, CancellationToken ct = default);
}

public interface IVectorStore
{
    Task UpsertAsync(IEnumerable<VectorRecord> records, CancellationToken ct = default);
    Task<IReadOnlyList<SearchHit>> SearchAsync(
        ReadOnlyMemory<float> query, int topK, string? filter = null, CancellationToken ct = default);
}

// Application service — pure orchestration, fully unit-testable with fakes.
public class DocumentIngestionService(
    IEmbeddingProvider embeddings,
    IVectorStore store,
    IChunker chunker)
{
    public async Task IngestAsync(Document document, CancellationToken ct = default)
    {
        var records = new List<VectorRecord>();

        foreach (var chunk in chunker.Split(document.Text))
        {
            var vector = await embeddings.EmbedAsync(chunk.Text, ct);
            records.Add(new VectorRecord(
                Id: $"{document.Id}:{chunk.Index}",
                Vector: vector,
                Metadata: new()
                {
                    ["documentId"] = document.Id.ToString(),
                    ["page"] = chunk.Page.ToString(),
                    // Written at ingestion so retrieval can filter by entitlement
                    // in the query instead of trusting the prompt.
                    ["acl"] = string.Join(',', document.AllowedGroups)
                }));
        }

        await store.UpsertAsync(records, ct);
    }
}

