// Aggregate root: Order owns its lines; the whole thing commits together.
public class Order
{
    private readonly List<OrderLine> _lines = [];

    public OrderId Id { get; private set; }
    // Another aggregate — referenced by ID, never by object reference.
    public CustomerId CustomerId { get; private set; }
    public OrderStatus Status { get; private set; }
    public IReadOnlyList<OrderLine> Lines => _lines;

    public Money Total => _lines.Aggregate(Money.Zero, (sum, l) => sum + l.LineTotal);

    public void AddLine(ProductId productId, int quantity, Money unitPrice)
    {
        // Invariants live on the aggregate, not in a service that callers may forget.
        if (Status != OrderStatus.Draft)
            throw new DomainException("Lines can only be added while the order is a draft.");
        if (quantity <= 0)
            throw new DomainException("Quantity must be positive.");

        var existing = _lines.SingleOrDefault(l => l.ProductId == productId);
        if (existing is not null) existing.IncreaseQuantity(quantity);
        else _lines.Add(new OrderLine(productId, quantity, unitPrice));
    }

    public void Submit()
    {
        if (_lines.Count == 0)
            throw new DomainException("An order needs at least one line.");

        Status = OrderStatus.Submitted;
        // Cross-aggregate work happens through an event, not a direct call,
        // so the transaction stays inside this boundary.
        DomainEvents.Raise(new OrderSubmitted(Id, CustomerId, Total));
    }
}

// Availability of a synchronous chain is the product of its links.
//   5 hops at 99.9%          -> 0.999^5  = 99.50%  (~3.6 h/month down)
//   5 hops at 99.99%         -> 0.9999^5 = 99.95%  (~22 min/month down)
//
// Asynchronous decoupling removes the hop from the caller's availability budget.

public class OrderService(IMessagePublisher publisher, IOrderRepository repository)
{
    public async Task<OrderResult> SubmitAsync(SubmitOrder command, CancellationToken ct)
    {
        var order = await repository.GetAsync(command.OrderId, ct);
        order.Submit();

        // The outbox makes the state change and the message atomic: both land in
        // one transaction, and a relay publishes afterwards. Without it a crash
        // between save and publish silently loses the event.
        await repository.SaveWithOutboxAsync(
            order,
            new OrderSubmitted(order.Id, order.CustomerId, order.Total),
            ct);

        // Billing may be down. The order is still accepted.
        return OrderResult.Accepted(order.Id, billingStatus: "pending");
    }
}

// Idempotent handler. At-least-once delivery means this WILL be called twice.
public class OrderSubmittedHandler(
    IProcessedMessageStore processed,
    IBillingService billing,
    ILogger<OrderSubmittedHandler> logger)
{
    public async Task HandleAsync(ServiceBusReceivedMessage message, CancellationToken ct)
    {
        // MessageId is the idempotency key. A duplicate is a no-op, not an error.
        if (await processed.ExistsAsync(message.MessageId, ct))
        {
            logger.LogInformation("Duplicate {MessageId} ignored", message.MessageId);
            return;
        }

        var evt = message.Body.ToObjectFromJson<OrderSubmitted>();

        try
        {
            await billing.CreateInvoiceAsync(evt.OrderId, evt.Total, ct);
            // Mark processed in the same transaction as the side effect where the
            // store supports it; otherwise mark after, and accept a rare retry.
            await processed.MarkAsync(message.MessageId, ct);
        }
        catch (TransientException) when (message.DeliveryCount < 5)
        {
            throw; // Let the broker redeliver with backoff.
        }
        catch (Exception ex)
        {
            // Permanent failure: dead-letter with a reason a human can act on.
            logger.LogError(ex, "Dead-lettering {MessageId}", message.MessageId);
            throw new ServiceBusDeadLetterException("InvoiceCreationFailed", ex.Message);
        }
    }
}

// Cache-aside with stampede protection and jittered expiry.
public class CachedEmbeddingProvider(
    IEmbeddingProvider inner,
    IDistributedCache cache) : IEmbeddingProvider
{
    private static readonly SemaphoreSlim[] Locks =
        Enumerable.Range(0, 64).Select(_ => new SemaphoreSlim(1, 1)).ToArray();

    public async Task<ReadOnlyMemory<float>> EmbedAsync(string text, CancellationToken ct = default)
    {
        var key = $"emb:{Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)))}";

        if (await cache.GetAsync(key, ct) is { } cached)
            return Deserialize(cached);

        // One caller per key recomputes; the rest wait and read the cached result.
        var gate = Locks[Math.Abs(key.GetHashCode()) % Locks.Length];
        await gate.WaitAsync(ct);
        try
        {
            if (await cache.GetAsync(key, ct) is { } raced) return Deserialize(raced);

            var vector = await inner.EmbedAsync(text, ct);

            // Jitter stops a batch of keys expiring in the same second.
            var ttl = TimeSpan.FromHours(24) + TimeSpan.FromMinutes(Random.Shared.Next(0, 120));
            await cache.SetAsync(key, Serialize(vector),
                new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = ttl }, ct);

            return vector;
        }
        finally { gate.Release(); }
    }
}

// Durable Functions: document ingestion with fan-out over chunks.
[Function(nameof(IngestDocumentOrchestrator))]
public static async Task<IngestResult> IngestDocumentOrchestrator(
    [OrchestrationTrigger] TaskOrchestrationContext context)
{
    var request = context.GetInput<IngestRequest>()!;

    // Each Call* is checkpointed. A crash resumes here, not at the beginning.
    var text = await context.CallActivityAsync<string>(nameof(ExtractText), request.BlobUri);
    var chunks = await context.CallActivityAsync<Chunk[]>(nameof(ChunkText), text);

    // Fan out: embeddings run in parallel, bounded by the activity's own throttle.
    var tasks = chunks.Select(c => context.CallActivityAsync<EmbeddedChunk>(nameof(EmbedChunk), c));
    var embedded = await Task.WhenAll(tasks);

    await context.CallActivityAsync(nameof(IndexChunks),
        new IndexRequest(request.DocumentId, embedded));

    // Deterministic replacement for DateTime.Now — orchestrators must be replayable.
    return new IngestResult(request.DocumentId, chunks.Length, context.CurrentUtcDateTime);
}

[Function(nameof(EmbedChunk))]
public static async Task<EmbeddedChunk> EmbedChunk(
    [ActivityTrigger] Chunk chunk, FunctionContext ctx)
{
    var embeddings = ctx.InstanceServices.GetRequiredService<IEmbeddingProvider>();
    var vector = await embeddings.EmbedAsync(chunk.Text);
    return new EmbeddedChunk(chunk, vector);
}

// Cosmos DB: the partition key is the decision that matters.
// Conversations partitioned by userId keep one user's history in one partition,
// which makes the common query single-partition and cheap.

var container = await database.CreateContainerIfNotExistsAsync(
    new ContainerProperties(id: "conversations", partitionKeyPath: "/userId")
    {
        // TTL housekeeping: transcripts expire automatically after 90 days
        // rather than needing a cleanup job nobody remembers to run.
        DefaultTimeToLive = (int)TimeSpan.FromDays(90).TotalSeconds,
        IndexingPolicy = new IndexingPolicy
        {
            // Message bodies are never filtered on; excluding them cuts RU cost
            // on every write.
            ExcludedPaths = { new ExcludedPath { Path = "/messages/*" } }
        }
    },
    throughput: ThroughputProperties.CreateAutoscaleThroughput(4000));

// Single-partition query: cheap and predictable.
var query = new QueryDefinition(
        "SELECT * FROM c WHERE c.userId = @userId ORDER BY c.updatedAt DESC OFFSET 0 LIMIT 20")
    .WithParameter("@userId", userId);

using var iterator = container.GetItemQueryIterator<Conversation>(
    query,
    requestOptions: new QueryRequestOptions { PartitionKey = new PartitionKey(userId) });

// DefaultAzureCredential: managed identity in Azure, developer credentials locally.
// The same code path in both environments, with no secret in either.
var credential = new DefaultAzureCredential(new DefaultAzureCredentialOptions
{
    ManagedIdentityClientId = builder.Configuration["Azure:UserAssignedClientId"]
});

builder.Configuration.AddAzureKeyVault(
    new Uri($"https://{builder.Configuration["Azure:KeyVaultName"]}.vault.azure.net/"),
    credential);

builder.Services.AddSingleton(new AzureOpenAIClient(
    new Uri(builder.Configuration["AzureOpenAI:Endpoint"]!), credential));

builder.Services.AddSingleton(new SearchClient(
    new Uri(builder.Configuration["Search:Endpoint"]!),
    builder.Configuration["Search:Index"], credential));

// Entitlements come from the token and are applied as a SEARCH FILTER.
// Putting them in the prompt would make them negotiable; a filter is not.
public async Task<IReadOnlyList<SearchHit>> SearchAsync(
    string query, ClaimsPrincipal user, CancellationToken ct)
{
    var groups = user.FindAll("groups").Select(c => c.Value).ToArray();
    if (groups.Length == 0) return [];

    var filter = string.Join(" or ", groups.Select(g => $"acl/any(a: a eq '{g.Replace("'", "''")}')"));

    var response = await searchClient.SearchAsync<SearchHit>(
        query, new SearchOptions { Filter = filter, Size = 10 }, ct);

    return response.Value.GetResults().Select(r => r.Document).ToList();
}

// One activity per AI request, carrying the fields you will actually query on.
public class InstrumentedChatService(
    IChatService inner,
    TelemetryClient telemetry) : IChatService
{
    private static readonly ActivitySource Source = new("Acme.Ai");

    public async Task<ChatResponse> CompleteAsync(ChatRequest request, CancellationToken ct)
    {
        using var activity = Source.StartActivity("ai.chat");
        var started = Stopwatch.GetTimestamp();

        activity?.SetTag("ai.model", request.Model);
        activity?.SetTag("ai.prompt_version", request.PromptVersion);
        activity?.SetTag("tenant.id", request.TenantId);

        try
        {
            var response = await inner.CompleteAsync(request, ct);

            activity?.SetTag("ai.prompt_tokens", response.Usage.PromptTokens);
            activity?.SetTag("ai.completion_tokens", response.Usage.CompletionTokens);
            activity?.SetTag("ai.cost_usd", response.Usage.EstimatedCostUsd);
            activity?.SetTag("ai.outcome", response.Outcome);

            // A metric, not a log line: this is what the cost dashboard aggregates.
            telemetry.GetMetric("ai.cost_usd", "model", "tenant")
                .TrackValue(response.Usage.EstimatedCostUsd, request.Model, request.TenantId);

            telemetry.GetMetric("ai.latency_ms", "model")
                .TrackValue(Stopwatch.GetElapsedTime(started).TotalMilliseconds, request.Model);

            return response;
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            throw;
        }
    }
}

