// DynamoDB single-table design: derive the keys from the access patterns.
//
// Access patterns required:
//   1. Get a conversation by id
//   2. List a user's conversations, most recent first
//   3. Get all messages in a conversation in order
//
// Base table: PK / SK
//   CONV#<id>   | META                -> conversation metadata
//   CONV#<id>   | MSG#<timestamp>     -> message, naturally ordered by SK
// GSI1: GSI1PK / GSI1SK
//   USER#<id>   | CONV#<updatedAt>    -> pattern 2, newest first

var request = new QueryRequest
{
    TableName = "conversations",
    KeyConditionExpression = "PK = :pk AND begins_with(SK, :prefix)",
    ExpressionAttributeValues = new Dictionary<string, AttributeValue>
    {
        [":pk"] = new($"CONV#{conversationId}"),
        [":prefix"] = new("MSG#")
    },
    ScanIndexForward = true   // chronological order comes free from the sort key
};

// Pattern 2 uses the index rather than scanning the table.
var listRequest = new QueryRequest
{
    TableName = "conversations",
    IndexName = "GSI1",
    KeyConditionExpression = "GSI1PK = :pk",
    ExpressionAttributeValues = new Dictionary<string, AttributeValue>
    {
        [":pk"] = new($"USER#{userId}")
    },
    ScanIndexForward = false, // newest first
    Limit = 20
};

{
  "Comment": "Document ingestion with retry, catch and compensation",
  "StartAt": "ExtractText",
  "States": {
    "ExtractText": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:extract-text",
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        { "ErrorEquals": ["States.ALL"], "Next": "MarkIngestionFailed" }
      ],
      "Next": "EmbedChunks"
    },
    "EmbedChunks": {
      "Type": "Map",
      "ItemsPath": "$.chunks",
      "MaxConcurrency": 10,
      "Iterator": {
        "StartAt": "Embed",
        "States": {
          "Embed": {
            "Type": "Task",
            "Resource": "arn:aws:lambda:us-east-1:123456789012:function:embed-chunk",
            "End": true
          }
        }
      },
      "Next": "IndexChunks"
    },
    "IndexChunks": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:index-chunks",
      "End": true
    },
    "MarkIngestionFailed": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:mark-failed",
      "End": true
    }
  }
}

# Terraform: private subnets plus a Bedrock VPC endpoint so model traffic
# never traverses the public internet.

resource "aws_vpc_endpoint" "bedrock_runtime" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.bedrock-runtime"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.bedrock_endpoint.id]
  private_dns_enabled = true

  # Belt and braces: even reaching the endpoint, only these models are callable.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = "*"
      Action    = ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"]
      Resource  = [
        "arn:aws:bedrock:${var.region}::foundation-model/anthropic.claude-3-5-sonnet-20241022-v2:0"
      ]
    }]
  })
}

resource "aws_security_group" "bedrock_endpoint" {
  name   = "bedrock-endpoint"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    # Only the orchestrator's security group, not the whole VPC CIDR.
    security_groups = [aws_security_group.orchestrator.id]
  }
}

// Bedrock Converse API with tool use. The same shape works across model
// families, so switching models stays a configuration change.
var client = new AmazonBedrockRuntimeClient(RegionEndpoint.USEast1);

var request = new ConverseRequest
{
    ModelId = "anthropic.claude-3-5-sonnet-20241022-v2:0",
    System = [new SystemContentBlock { Text = "You are a claims assistant. Cite policy sections." }],
    Messages =
    [
        new Message
        {
            Role = ConversationRole.User,
            Content = [new ContentBlock { Text = "Is water damage covered under policy P-4471?" }]
        }
    ],
    ToolConfig = new ToolConfiguration
    {
        Tools =
        [
            new Tool
            {
                ToolSpec = new ToolSpecification
                {
                    Name = "lookup_policy",
                    Description = "Retrieve the clauses of a policy by its number.",
                    InputSchema = new ToolInputSchema
                    {
                        Json = Document.FromObject(new
                        {
                            type = "object",
                            properties = new { policyNumber = new { type = "string" } },
                            required = new[] { "policyNumber" }
                        })
                    }
                }
            }
        ]
    },
    InferenceConfig = new InferenceConfiguration { MaxTokens = 1024, Temperature = 0.2f }
};

var response = await client.ConverseAsync(request);

// The model asks for a tool; YOUR code decides whether this caller may run it.
if (response.StopReason == StopReason.Tool_use)
{
    // Authorise here — never assume the model's request is permitted.
}
